import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type CybersecurityIntroProps = Record<string, any>;

const CybersecurityIntro: React.FC<CybersecurityIntroProps> = ({
  backgroundColor = "#07090F",
  transparentBackground = false,
  durationInSeconds = 4,
  primaryAccent = "#FF84AF",
  secondaryAccent = "#FB936E",
  mainText = "Streamline early security review",
  subText = "Get time-saving insights",
  particleCount = 50,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for backgrounds
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Global animations
  const pulseBlur = interpolate(Math.sin(frame / 8), [-1, 1], [10, 25]);
  const ambientSway = interpolate(Math.sin(frame / 20), [-1, 1], [-5, 5]);

  // Scanline motion:
  // 0 - 1.2s (frame 0-36): sweep in to the text
  // 1.2 - 2.6s (frame 36-78): sweep precisely across the text
  // 2.6 - 4.0s (frame 78-120): sweep out to the right edge
  const scanX = interpolate(
    frame,
    [0, 36, 78, 110],
    [-width * 0.2, width * 0.2, width * 0.8, width * 1.5],
    { extrapolateRight: "clamp" }
  );

  // Text masking logic synced perfectly with scanline position
  // Clamped to avoid negative inset values or values > width
  const textMaskRightInset = Math.min(width, Math.max(0, width - scanX));
  const textClipPath = `inset(0px ${textMaskRightInset}px 0px 0px)`;

  // Subtext animations (starts at 2.6s / frame 78)
  const subTextOpacity = interpolate(frame, [78, 93], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const subTextSpring = spring({
    fps,
    frame: Math.max(0, frame - 78),
    config: { damping: 14, mass: 0.8 },
  });
  const subTextY = interpolate(subTextSpring, [0, 1], [30, 0]);

  // Generative high-tech particles (nodes and lines)
  const nodes = useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => {
      const isLine = random(`isLine-${i}`) > 0.8;
      return {
        id: i,
        x: random(`nx-${i}`) * width,
        y: random(`ny-${i}`) * height,
        size: random(`nsize-${i}`) * 2 + 2,
        isLine,
        lineWidth: random(`nlw-${i}`) * 100 + 30,
      };
    });
  }, [particleCount, width, height]);

  const trailWidth = width * 0.4;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden", transition: "none" }}>
      
      {/* Background Digital Grid */}
      <svg width="100%" height="100%" style={{ position: "absolute", opacity: 0.1, transition: "none" }}>
        <defs>
          <pattern id="grid" width="60" height="60" patternUnits="userSpaceOnUse">
            <path d="M 60 0 L 0 0 0 60" fill="none" stroke="#ffffff" strokeWidth="1" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#grid)" />
      </svg>

      {/* Cinematic Vignette */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `radial-gradient(circle at center, transparent 30%, ${backgroundColor} 100%)`,
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* Particles and Lines Layer */}
      {nodes.map((n) => {
        const dist = scanX - n.x;
        const isActive = dist >= 0;
        
        // Particles flare up when the scanline passes them, then decay to a gentle ambient glow
        const opacity = isActive
          ? interpolate(dist, [0, 50, 300, 1000], [0.8, 1, 0.3, 0.15], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            })
          : 0;

        const color = n.id % 2 === 0 ? primaryAccent : secondaryAccent;
        const offsetY = interpolate(Math.sin((frame + n.id * 10) / 20), [-1, 1], [-4, 4]);

        if (n.isLine) {
          return (
            <div
              key={n.id}
              style={{
                position: "absolute",
                left: n.x,
                top: n.y + offsetY,
                width: n.lineWidth,
                height: 1,
                backgroundColor: color,
                opacity: opacity * 0.5,
                boxShadow: `0 0 8px 1px ${color}`,
                transition: "none",
              }}
            />
          );
        }

        return (
          <div
            key={n.id}
            style={{
              position: "absolute",
              left: n.x,
              top: n.y + offsetY,
              width: n.size,
              height: n.size,
              borderRadius: "50%",
              backgroundColor: color,
              opacity,
              boxShadow: `0 0 10px 2px ${color}`,
              mixBlendMode: "screen",
              transition: "none",
            }}
          />
        );
      })}

      {/* Subtext Layer (Base Layer) */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
        }}
      >
        <div style={{ height: 100 }} /> {/* Spacer matching Main Text height */}
        <div style={{ height: 80, display: "flex", alignItems: "center" }}>
          <h2
            style={{
              opacity: subTextOpacity,
              transform: `translateY(${subTextY}px)`,
              fontSize: 48,
              fontWeight: 400,
              color: secondaryAccent,
              textShadow: `0 0 ${pulseBlur}px ${secondaryAccent}66`,
              margin: 0,
              transition: "none",
            }}
          >
            {subText}
          </h2>
        </div>
      </div>

      {/* Main Text Layer (Masked by Scanline) */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          clipPath: textClipPath,
          transition: "none",
        }}
      >
        <div style={{ height: 100, display: "flex", alignItems: "center" }}>
          <h1
            style={{
              fontSize: 72,
              fontWeight: 600,
              color: "#ffffff",
              letterSpacing: "-0.02em",
              margin: 0,
              textShadow: `0 0 ${pulseBlur}px ${primaryAccent}80`,
              transform: `translateY(${ambientSway * 0.5}px)`,
              transition: "none",
            }}
          >
            {mainText}
          </h1>
        </div>
        <div style={{ height: 80 }} /> {/* Spacer matching Subtext height */}
      </div>

      {/* Sweeping Scanline */}
      <div
        style={{
          position: "absolute",
          top: 0,
          bottom: 0,
          left: scanX - trailWidth,
          width: trailWidth,
          background: `linear-gradient(to right, transparent, ${primaryAccent}40, ${secondaryAccent}ff)`,
          opacity: interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" }),
          borderRight: `3px solid #ffffff`,
          boxShadow: `20px 0 60px 10px ${secondaryAccent}`,
          zIndex: 10,
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default CybersecurityIntro;